"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["26961"],{19485(e){e.exports=JSON.parse('{"id":"FIN-1236","slug":"net-exports","term":"Net Exports","also_known_as":[],"difficulty":"Advanced","definition":"Net exports are the value of a country\'s exports of goods and services minus the value of its imports over a period.","explanation":["Net exports are one of the components of GDP, alongside household consumption, investment and government spending. Exports add to domestic production, while imports are subtracted because they represent spending on goods and services produced abroad.","For example, if a country exports goods and services worth 500 billion and imports 560 billion, its net exports are minus 60 billion, meaning it has a trade deficit.","Positive net exports, a trade surplus, mean the country sells more abroad than it buys. Negative net exports, a trade deficit, mean it buys more than it sells.","Net exports are influenced by exchange rates, economic growth at home and abroad, competitiveness and trade policies. A weaker currency tends to boost exports and reduce imports, while strong domestic demand tends to increase imports. A trade deficit is not necessarily harmful; it can reflect strong domestic demand or investment financed by foreign capital, although persistent large deficits may raise concerns about sustainability."],"note":"","total":1725,"prev":{"slug":"net-debt-to-ebitda","term":"Net Debt to EBITDA"},"next":{"slug":"net-income-accounting","term":"Net Income (Accounting)"}}')}}]);